<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $request = Illuminate\Http\Request::create('http://shop-amsterdam.localhost/seller/products/1/edit', 'GET'); $request->headers->set('HOST', 'shop-amsterdam.localhost'); $user = \App\Models\User::find(1); Illuminate\Support\Facades\Auth::login($user); try { $response = app()->handle($request); if ($response->exception) { echo $response->exception->getMessage(); } else { echo 'Success'; } } catch (\Throwable $e) { echo $e->getMessage(); }
